export function getKipperCard(id: number): KipperCardDef | undefined {
  return KIPPER_CARDS.find(c => c.id === id);
}

export function getAllKipperCards(): KipperCardDef[] {
  return KIPPER_CARDS;
}

export function shuffleArray<T>(array: T[]): T[] {
  const a = [...array];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

export type SpreadType = "three" | "five" | "seven" | "line";

export interface SpreadDef {
  type: SpreadType;
  name: string;
  description: string;
  cardCount: number;
  positions: string[];
}

